-- Generated by scripts/generate/generate.mjs from shared/deal/ (workstream B). Don't edit by hand.

CREATE TABLE IF NOT EXISTS LShufWork_Civ (CivilizationType TEXT PRIMARY KEY, Age TEXT, Rank INTEGER, GRank INTEGER, GK INTEGER, GPos INTEGER, GN INTEGER, Donor TEXT);
DELETE FROM LShufWork_Civ;
INSERT INTO LShufWork_Civ (CivilizationType, Age) SELECT CivilizationType, COALESCE(MIN(Age), '') FROM LegacyCivilizations
  WHERE CivilizationType IS NOT (SELECT b.Civ FROM LShufWork_Build b WHERE b.Own = 1 AND b.OK = 1) GROUP BY CivilizationType;
UPDATE LShufWork_Civ SET Rank = (SELECT COUNT(*) FROM LShufWork_Civ o WHERE 1 = 1 AND (o.CivilizationType < LShufWork_Civ.CivilizationType)) WHERE 1 = 1;
UPDATE LShufWork_Civ SET GRank = (SELECT COUNT(*) FROM LShufWork_Civ o WHERE o.Age = LShufWork_Civ.Age AND (o.CivilizationType < LShufWork_Civ.CivilizationType)) WHERE 1 = 1;
UPDATE LShufWork_Civ SET GK = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (GRank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (GRank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (GRank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (GRank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859),
  GN = (SELECT COUNT(*) FROM LShufWork_Civ o WHERE o.Age = LShufWork_Civ.Age);
UPDATE LShufWork_Civ SET GPos = (SELECT COUNT(*) FROM LShufWork_Civ o WHERE o.Age = LShufWork_Civ.Age AND (o.GK < LShufWork_Civ.GK OR (o.GK = LShufWork_Civ.GK AND (o.CivilizationType < LShufWork_Civ.CivilizationType)))) WHERE 1 = 1;
UPDATE LShufWork_Civ SET Donor = CASE WHEN GN >= 2 THEN (SELECT o.CivilizationType FROM LShufWork_Civ o
  WHERE o.Age = LShufWork_Civ.Age AND o.GPos = (LShufWork_Civ.GPos + 1) % LShufWork_Civ.GN) ELSE CivilizationType END;

CREATE TABLE IF NOT EXISTS LShufWork_BRow (TableName TEXT, LeaderType TEXT, CivilizationType TEXT, TargetType TEXT, Score INTEGER);
DELETE FROM LShufWork_BRow;
INSERT INTO LShufWork_BRow (TableName, LeaderType, CivilizationType, TargetType, Score)
SELECT 'StartBiasBiomes', LeaderType, CivilizationType, BiomeType, Score FROM StartBiasBiomes
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasTerrains', LeaderType, CivilizationType, TerrainType, Score FROM StartBiasTerrains
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasAdjacentToCoasts', LeaderType, CivilizationType, NULL, Score FROM StartBiasAdjacentToCoasts
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasFeatureClasses', LeaderType, CivilizationType, FeatureClassType, Score FROM StartBiasFeatureClasses
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasRivers', LeaderType, CivilizationType, NULL, Score FROM StartBiasRivers
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasLakes', LeaderType, CivilizationType, NULL, Score FROM StartBiasLakes
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasNaturalWonders', LeaderType, CivilizationType, NULL, Score FROM StartBiasNaturalWonders
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasIslands', LeaderType, CivilizationType, NULL, Score FROM StartBiasIslands
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL
UNION ALL SELECT 'StartBiasResources', LeaderType, CivilizationType, ResourceType, Score FROM StartBiasResources
  WHERE LeaderType IS NOT NULL OR CivilizationType IS NOT NULL;
CREATE TABLE IF NOT EXISTS LShufWork_BStat (TableName TEXT PRIMARY KEY, Ord INTEGER, HasTarget INTEGER, W INTEGER, Start INTEGER, NT INTEGER, LW INTEGER, LStart INTEGER, LNT INTEGER, LLo INTEGER, LHi INTEGER, CLo INTEGER, CHi INTEGER);
DELETE FROM LShufWork_BStat;
INSERT INTO LShufWork_BStat (TableName, Ord, HasTarget) SELECT 'StartBiasBiomes', 0, 1 UNION ALL SELECT 'StartBiasTerrains', 1, 1 UNION ALL SELECT 'StartBiasAdjacentToCoasts', 2, 0 UNION ALL SELECT 'StartBiasFeatureClasses', 3, 1 UNION ALL SELECT 'StartBiasRivers', 4, 0 UNION ALL SELECT 'StartBiasLakes', 5, 0 UNION ALL SELECT 'StartBiasNaturalWonders', 6, 0 UNION ALL SELECT 'StartBiasIslands', 7, 0 UNION ALL SELECT 'StartBiasResources', 8, 1;
UPDATE LShufWork_BStat SET W = (SELECT COUNT(*) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName),
  NT = CASE WHEN HasTarget = 1 THEN (SELECT COUNT(DISTINCT r.TargetType) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.TargetType IS NOT NULL) ELSE 0 END,
  LLo = COALESCE((SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NOT NULL), (SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName)),
  LHi = COALESCE((SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NOT NULL), (SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName)),
  CLo = COALESCE((SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NULL AND r.CivilizationType IS NOT NULL), (SELECT MIN(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName)),
  CHi = COALESCE((SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NULL AND r.CivilizationType IS NOT NULL), (SELECT MAX(r.Score) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName));
UPDATE LShufWork_BStat SET Start = COALESCE((SELECT SUM(o.W) FROM LShufWork_BStat o WHERE o.Ord < LShufWork_BStat.Ord), 0);
-- Leaders roll from the leader rows alone, the same in every age (lshuf-deal-bias-stats.js biasStats).
UPDATE LShufWork_BStat SET LW = (SELECT COUNT(*) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NOT NULL),
  LNT = CASE WHEN HasTarget = 1 THEN (SELECT COUNT(DISTINCT r.TargetType) FROM LShufWork_BRow r WHERE r.TableName = LShufWork_BStat.TableName AND r.LeaderType IS NOT NULL AND r.TargetType IS NOT NULL) ELSE 0 END;
UPDATE LShufWork_BStat SET LStart = COALESCE((SELECT SUM(o.LW) FROM LShufWork_BStat o WHERE o.Ord < LShufWork_BStat.Ord), 0);
CREATE TABLE IF NOT EXISTS LShufWork_BTarget (TableName TEXT, TargetType TEXT, Rank INTEGER, PRIMARY KEY (TableName, TargetType));
DELETE FROM LShufWork_BTarget;
INSERT INTO LShufWork_BTarget (TableName, TargetType) SELECT DISTINCT r.TableName, r.TargetType FROM LShufWork_BRow r
  JOIN LShufWork_BStat b ON b.TableName = r.TableName AND b.HasTarget = 1 WHERE r.TargetType IS NOT NULL;
UPDATE LShufWork_BTarget SET Rank = (SELECT COUNT(*) FROM LShufWork_BTarget o WHERE o.TableName = LShufWork_BTarget.TableName AND (o.TargetType < LShufWork_BTarget.TargetType)) WHERE 1 = 1;
CREATE TABLE IF NOT EXISTS LShufWork_BLTarget (TableName TEXT, TargetType TEXT, Rank INTEGER, PRIMARY KEY (TableName, TargetType));
DELETE FROM LShufWork_BLTarget;
INSERT INTO LShufWork_BLTarget (TableName, TargetType) SELECT DISTINCT r.TableName, r.TargetType FROM LShufWork_BRow r
  JOIN LShufWork_BStat b ON b.TableName = r.TableName AND b.HasTarget = 1 WHERE r.TargetType IS NOT NULL AND r.LeaderType IS NOT NULL;
UPDATE LShufWork_BLTarget SET Rank = (SELECT COUNT(*) FROM LShufWork_BLTarget o WHERE o.TableName = LShufWork_BLTarget.TableName AND (o.TargetType < LShufWork_BLTarget.TargetType)) WHERE 1 = 1;
CREATE TABLE IF NOT EXISTS LShufWork_BShape (Total INTEGER, LTotal INTEGER, LWith INTEGER, L2 INTEGER, CWith INTEGER, C2 INTEGER, CivCount INTEGER);
DELETE FROM LShufWork_BShape;
INSERT INTO LShufWork_BShape SELECT (SELECT COUNT(*) FROM LShufWork_BRow),
  (SELECT COUNT(*) FROM LShufWork_BRow WHERE LeaderType IS NOT NULL),
  (SELECT COUNT(DISTINCT LeaderType) FROM LShufWork_BRow WHERE LeaderType IS NOT NULL),
  (SELECT COUNT(*) FROM (SELECT LeaderType FROM LShufWork_BRow WHERE LeaderType IS NOT NULL GROUP BY LeaderType HAVING COUNT(*) >= 2)),
  (SELECT COUNT(DISTINCT CivilizationType) FROM LShufWork_BRow WHERE LeaderType IS NULL AND CivilizationType IS NOT NULL),
  (SELECT COUNT(*) FROM (SELECT CivilizationType FROM LShufWork_BRow WHERE LeaderType IS NULL AND CivilizationType IS NOT NULL
    GROUP BY CivilizationType HAVING COUNT(*) >= 2)),
  (SELECT COUNT(*) FROM LShufWork_Civ);

CREATE TABLE IF NOT EXISTS LShufWork_RSub (Subj TEXT, IsCiv INTEGER, Base INTEGER, Cnt INTEGER, PRIMARY KEY (Subj, IsCiv));
