UPDATE LShufWork_RSub SET Cnt = CASE WHEN IsCiv = 1 THEN CASE WHEN (SELECT CivCount FROM LShufWork_BShape) = 0 OR (SELECT CWith FROM LShufWork_BShape) = 0 THEN 0
    WHEN ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (Base) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (Base) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (Base) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (9) * 104729 + (Base) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % (SELECT CivCount FROM LShufWork_BShape) >= (SELECT CWith FROM LShufWork_BShape) THEN 0
    WHEN ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % (SELECT CWith FROM LShufWork_BShape) < (SELECT C2 FROM LShufWork_BShape) THEN 2 ELSE 1 END ELSE CASE WHEN (SELECT LWith FROM LShufWork_BShape) = 0 THEN 1
    WHEN ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (5) * 104729 + (Base) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % (SELECT LWith FROM LShufWork_BShape) < (SELECT L2 FROM LShufWork_BShape) THEN 2 ELSE 1 END END;
