  AND b.W > 0 AND ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % CASE WHEN IsCiv = 1 THEN (SELECT Total FROM LShufWork_BShape) ELSE (SELECT LTotal FROM LShufWork_BShape) END >= b.Start AND ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % CASE WHEN IsCiv = 1 THEN (SELECT Total FROM LShufWork_BShape) ELSE (SELECT LTotal FROM LShufWork_BShape) END < b.Start + b.W) WHERE IsCiv = 1;
UPDATE LShufWork_Roll SET TableName = (SELECT b.TableName FROM LShufWork_BStat b WHERE IsCiv = 0
  AND b.LW > 0 AND ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % CASE WHEN IsCiv = 1 THEN (SELECT Total FROM LShufWork_BShape) ELSE (SELECT LTotal FROM LShufWork_BShape) END >= b.LStart AND ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (6) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % CASE WHEN IsCiv = 1 THEN (SELECT Total FROM LShufWork_BShape) ELSE (SELECT LTotal FROM LShufWork_BShape) END < b.LStart + b.LW) WHERE IsCiv = 0;
UPDATE LShufWork_Roll SET TargetType = CASE WHEN (SELECT b.NT FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) > 0 THEN (SELECT t.TargetType FROM LShufWork_BTarget t
  WHERE t.TableName = LShufWork_Roll.TableName AND t.Rank = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % (SELECT b.NT FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName)) ELSE NULL END
  WHERE IsCiv = 1;
UPDATE LShufWork_Roll SET TargetType = CASE WHEN (SELECT b.LNT FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) > 0 THEN (SELECT t.TargetType FROM LShufWork_BLTarget t
  WHERE t.TableName = LShufWork_Roll.TableName AND t.Rank = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (7) * 104729 + (LShufWork_Roll.R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % (SELECT b.LNT FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName)) ELSE NULL END
  WHERE IsCiv = 0;
UPDATE LShufWork_Roll SET Score = CASE WHEN TableName = 'StartBiasIslands' THEN CASE WHEN IsCiv = 1 THEN (SELECT b.CHi FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) ELSE (SELECT b.LHi FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) END
  ELSE CASE WHEN IsCiv = 1 THEN (SELECT b.CLo FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) ELSE (SELECT b.LLo FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) END + 5 * (((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (8) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (8) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (8) * 104729 + (R) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (8) * 104729 + (R) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859) % (((CASE WHEN IsCiv = 1 THEN (SELECT b.CHi FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) ELSE (SELECT b.LHi FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) END) - (CASE WHEN IsCiv = 1 THEN (SELECT b.CLo FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) ELSE (SELECT b.LLo FROM LShufWork_BStat b WHERE b.TableName = LShufWork_Roll.TableName) END)) / 5 + 1)) END;
