  FROM LShufWork_TSeg WHERE instr(substr(Rest, 2), '|') > 1;
UPDATE LShufWork_TSeg SET Rest = substr(Rest, instr(substr(Rest, 2), '|') + 1) WHERE instr(substr(Rest, 2), '|') > 0;
